import java.util.*;

public class Solution {
    static class Node {
        int val;
        Node esq, dir;
        Node(int val, Node esq, Node dir) { this.val = val; this.esq = esq; this.dir = dir; }
    }

    static List<Integer> preOrdem(Node r) {
        List<Integer> out = new ArrayList<>();
        pre(r, out);
        return out;
    }

    private static void pre(Node n, List<Integer> out) {
        if (n == null) return;
        out.add(n.val);
        pre(n.esq, out);
        pre(n.dir, out);
    }

    // Desce à esquerda empilhando; ao voltar, visita e vai para a direita. O(n), pilha O(h).
    static List<Integer> emOrdemIterativa(Node r) {
        List<Integer> out = new ArrayList<>();
        Deque<Node> pilha = new ArrayDeque<>();
        Node atual = r;
        while (atual != null || !pilha.isEmpty()) {
            while (atual != null) {
                pilha.push(atual);
                atual = atual.esq;
            }
            atual = pilha.pop();
            out.add(atual.val);
            atual = atual.dir;
        }
        return out;
    }

    static List<Integer> posOrdem(Node r) {
        List<Integer> out = new ArrayList<>();
        pos(r, out);
        return out;
    }

    private static void pos(Node n, List<Integer> out) {
        if (n == null) return;
        pos(n.esq, out);
        pos(n.dir, out);
        out.add(n.val);
    }

    static List<List<Integer>> porNiveis(Node r) {
        List<List<Integer>> out = new ArrayList<>();
        if (r == null) return out;
        ArrayDeque<Node> fila = new ArrayDeque<>();
        fila.add(r);
        while (!fila.isEmpty()) {
            List<Integer> nivel = new ArrayList<>();
            for (int i = fila.size(); i > 0; i--) {
                Node n = fila.poll();
                nivel.add(n.val);
                if (n.esq != null) fila.add(n.esq);
                if (n.dir != null) fila.add(n.dir);
            }
            out.add(nivel);
        }
        return out;
    }
}

