import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    private static Solution.Node n(int v, Solution.Node e, Solution.Node d) { return new Solution.Node(v, e, d); }
    private static Solution.Node f(int v) { return new Solution.Node(v, null, null); }

    //        4
    //      2   6
    //     1 3 5 7
    private static final Solution.Node T = n(4, n(2, f(1), f(3)), n(6, f(5), f(7)));

    @Test void preEPos() {
        assertEquals(List.of(4, 2, 1, 3, 6, 5, 7), Solution.preOrdem(T));
        assertEquals(List.of(1, 3, 2, 5, 7, 6, 4), Solution.posOrdem(T));
    }

    @Test void emOrdem() {
        assertEquals(List.of(1, 2, 3, 4, 5, 6, 7), Solution.emOrdemIterativa(T));
        assertEquals(List.of(), Solution.emOrdemIterativa(null));
    }

    @Test void niveis() {
        assertEquals(List.of(List.of(4), List.of(2, 6), List.of(1, 3, 5, 7)), Solution.porNiveis(T));
        assertEquals(List.of(), Solution.porNiveis(null));
    }

    @Test void degeneradaNaoEstouraAPilha() {
        Solution.Node raiz = null;
        for (int i = 0; i < 100_000; i++) raiz = n(i, raiz, null); // tudo à esquerda
        List<Integer> r = Solution.emOrdemIterativa(raiz);
        assertEquals(100_000, r.size());
        assertEquals(0, r.get(0));
        assertEquals(99_999, r.get(99_999));
    }
}
